import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  const card = new Group();

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const resources = [];
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(
      parseInt(colors.ink.slice(1, 3), 16) / 255,
      parseInt(colors.ink.slice(3, 5), 16) / 255,
      parseInt(colors.ink.slice(5, 7), 16) / 255
    ),
    vec3(
      parseInt(colors.surface.slice(1, 3), 16) / 255,
      parseInt(colors.surface.slice(3, 5), 16) / 255,
      parseInt(colors.surface.slice(5, 7), 16) / 255
    ),
    smoothstep(0.04, 0.96, uv().y)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new PlaneGeometry(3.2, 0.72);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.52,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.9, -0.42);
  shadow.scale.set(1, 0.38, 1);
  card.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardGeometry = new PlaneGeometry(2.56, 1.6);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: colors.paper
  });
  const cardSurface = new Mesh(cardGeometry, cardMaterial);
  cardSurface.position.set(0, 0, 0);
  cardSurface.onBeforeRender = (_renderer, _scene, camera) => {
    cardSurface.quaternion.copy(camera.quaternion);
  };
  card.add(cardSurface);
  resources.push(cardGeometry, cardMaterial);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: colors.ink
  });
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });

  const topFrameGeometry = new BoxGeometry(2.64, 0.045, 0.045);
  const sideFrameGeometry = new BoxGeometry(0.045, 1.6, 0.045);
  const accentGeometry = new BoxGeometry(0.42, 0.045, 0.05);

  const topFrame = new Mesh(topFrameGeometry, frameMaterial);
  topFrame.position.set(0, 0.82, 0.08);

  const bottomFrame = new Mesh(topFrameGeometry, frameMaterial);
  bottomFrame.position.set(0, -0.82, 0.08);

  const leftFrame = new Mesh(sideFrameGeometry, frameMaterial);
  leftFrame.position.set(-1.3, 0, 0.08);

  const rightFrame = new Mesh(sideFrameGeometry, frameMaterial);
  rightFrame.position.set(1.3, 0, 0.08);

  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-0.82, -0.68, 0.12);

  card.add(topFrame, bottomFrame, leftFrame, rightFrame, accent);
  resources.push(
    topFrameGeometry,
    sideFrameGeometry,
    accentGeometry,
    frameMaterial,
    accentMaterial
  );

  root.add(card);

  let loadedTexture = null;
  if (config?.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose();
        return;
      }

      loadedTexture = texture;
      const image = texture.image;
      const width = image?.width || 512;
      const height = image?.height || 320;
      const source = config?.atlasRegion?.sourceRect ?? { x: 0, y: 0, width: 512, height: 320 };

      texture.wrapS = ctx.THREE.ClampToEdgeWrapping;
      texture.wrapT = ctx.THREE.ClampToEdgeWrapping;
      texture.repeat.set(source.width / width, source.height / height);
      texture.offset.set(
        source.x / width,
        1 - (source.y + source.height) / height
      );

      if ('colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }

      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    card.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    }
  );

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    entrance.kill();

    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    root.traverse((object) => {
      object.onBeforeRender = null;
    });
  };

  return root;
}
